  1	// A LIFO queue (aka a stack) with limited capacity.
  2	class LimitedStack{
  3	 
  4	      var capacity : int; // capacity, max number of elements allowed on the stack.
  5	      var arr : array<int>; // contents of stack.
  6	      var top : int; // The index of the top of the stack, or -1 if the stack is empty
  7	
  8	      // This predicate express a class invariant: All objects of this calls should satisfy this.
  9	      predicate Valid()
 10	      reads this;
 11	      {
 12	        arr != null && capacity > 0 && capacity == arr.Length &&  top >= -1 && top < capacity 
 13	      }
 14	
 15	      predicate Empty()
 16	      reads this`top;
 17	      {
 18	            top == -1
 19	      }
 20	
 21	      predicate Full()
 22	      reads this`top, this`capacity;
 23	      {
 24	        top == (capacity - 1)
 25	      }
 26	  
 27	      method Init(c : int)
 28	      modifies this;
 29	      requires c > 0
 30	      ensures Valid() && Empty() && c == capacity
 31	      ensures fresh(arr); // ensures arr is a newly created object.
 32	      // Additional post-condition to be given here!
 33	      {
 34	        capacity := c;
 35	        arr := new int[c];
 36	        top := -1;
 37	      }
 38	
 39	
 40	      
 41	      method isEmpty() returns (res : bool)
 42	      ensures res == Empty()
 43	      {
 44	        if(top == -1)
 45	        { return true; }
 46	        else {
 47	              return false;
 48	        }
 49	      }
 50	
 51	
 52	
 53	      // Returns the top element of the stack, without removing it.
 54	      method Peek() returns (elem : int) 
 55	      requires Valid() && !Empty()
 56	      ensures elem == arr[top]
 57	      {
 58	            return arr[top]; 
 59	      }
 60	
 61	
 62	
 63	      // Pushed an element to the top of a (non full) stack. 
 64	      method Push(elem : int)
 65	      modifies this`top, this.arr 
 66	      requires Valid()
 67	      requires !Full() 
 68	      ensures Valid() && top == old(top) + 1 && arr[top] == elem
 69	      ensures !old(Empty()) ==> forall i : int :: 0 <= i <= old(top)  ==> arr[i] == old(arr[i]);
 70	      {
 71	            top := top + 1;
 72	            arr[top] := elem;
 73	      }
 74	
 75	      // Pops the top element off the stack.
 76	
 77	      method Pop() returns (elem : int)
 78	      modifies   this`top
 79	      requires Valid() && !Empty()  
 80	      ensures Valid()  && top == old(top) - 1 
 81	      ensures elem == arr[old(top)] 
 82	      {
 83	            elem := arr[top];
 84	            top := top - 1;
 85	            return elem;
 86	      }
 87	
 88	 
 89	      method Shift()
 90	      requires Valid() && !Empty();
 91	      ensures Valid();
 92	      ensures forall i : int :: 0 <= i < capacity - 1 ==> arr[i] == old(arr[i + 1]);
 93	      ensures top == old(top) - 1;
 94	      modifies this.arr, this`top;
 95	      {
 96	        var i : int := 0;
 97	        while (i < capacity - 1 )
 98	        invariant 0 <= i < capacity;
 99	        invariant forall j : int :: 0 <= j < i ==> arr[j] == old(arr[j + 1]);
100	        invariant forall j : int :: i <= j < capacity ==> arr[j] == old(arr[j]);
101	        {
102	          arr[i] := arr[i + 1];
103	          i := i + 1;
104	        }
105	        top := top - 1;
106	      }
107	
108	 
109	      //Push onto full stack, oldest element is discarded.
110	      method Push2(elem : int)
111	      modifies this.arr, this`top
112	      requires Valid()
113	      ensures Valid() && !Empty() 
114	      ensures arr[top] == elem
115	      ensures old(!Full()) ==> top == old(top) + 1 && old(Full()) ==> top == old(top)
116	      ensures ((old(Full()) ==> arr[capacity - 1] == elem)  && (old(!Full()) ==> (top == old(top) + 1 && arr[top] == elem) ))
117	      ensures old(Full()) ==> forall i : int :: 0 <= i < capacity - 1 ==> arr[i] == old(arr[i + 1]);
118	      {
119	            if(top == capacity - 1){
120	                  Shift();
121	                  top := top + 1;
122	                  arr[top] := elem;
123	            }
124	            else{
125	                  top := top + 1;
126	                  arr[top] := elem;
127	            }
128	      }
129	 
130	
131	 
132	
133	// When you are finished,  all the below assertions should be provable. 
134	// Feel free to add extra ones as well.
135	      method Main(){
136	           var s := new LimitedStack;
137	           s.Init(3);
138	
139	           assert s.Empty() && !s.Full(); 
140	
141	           s.Push(27);
142	           assert !s.Empty();
143	
144	           var e := s.Pop();
145	           assert e == 27;
146	
147	           assert s.top == -1; 
148	           assert s.Empty() && !s.Full(); 
149	           
150	           s.Push(5);
151	
152	           assert s.top == 0;
153	           assert s.capacity == 3;
154	           s.Push(32);
155	           s.Push(9);
156	           assert s.Full();
157	
158	           assert s.arr[0] == 5;
159	
160	           var e2 := s.Pop();
161	           
162	           assert e2 == 9 && !s.Full(); 
163	           assert s.arr[0] == 5;
164	
165	           s.Push(e2);
166	           s.Push2(99);
167	
168	           var e3 := s.Peek();
169	           assert e3 == 99;
170	           assert s.arr[0] == 32;
171	                     
172	       }
173	
174	}
